-- Function: public.fn_get_all_development_areas
-- Backup generated on 2026-10-25 20:32:59

CREATE OR REPLACE FUNCTION public.fn_get_all_development_areas(p_tenant_id uuid DEFAULT NULL::uuid)  RETURNS TABLE(id uuid, tenant_id uuid, name character varying, code character varying, description text, icon character varying, color_hex character varying, display_order integer, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone)  LANGUAGE plpgsql AS $function$ BEGIN     RETURN QUERY     SELECT da.id, da.tenant_id, da.name, da.code, da.description, da.icon, da.color_hex,            da.display_order, da.is_active, da.created_at, da.updated_at     FROM development_areas da     WHERE (da.tenant_id IS NULL OR da.tenant_id = p_tenant_id) AND da.is_active = TRUE     ORDER BY da.display_order; END; $function$ ;
